# [v1.2.81 修改时间 2026-10-22] AUD97 第二十七轮零预设独立审计 · 收尾修复(GBK 直改, 编码不变):
#   1) 委托侧代码匹配(4 处)改大小写不敏感 —— AUD96-10 只改了持仓查询侧, 委托侧仍是严格比较:
#      券商返回的代码后缀若非大写 -> 活跃买单查不到 -> 在途台账被清 -> 重复下单;
#      委托计数返回 0 -> 误报「委托未到券商/模拟模式」; 卖侧活跃单查不到 -> 卖单未成交却已恢复状态。
#   2) _read_order_direction 逐字段回退: 首个字段值域不认时继续试下一个, 不再一票否决方向判定。
#   3) 方向字段自检改用统一语义(0=买/1=卖/未知)统计, 并如实描述未知委托的处置
#      (原写「将按 48(买单) 保守判定」, 与 AUD96-3 之后的实现不符)。
#   4) 修 AUD96 引入的落盘回归: _read_file_bytes 对「文件不存在」也返回 None, AUD96 一律当成
#      「读失败 -> 中止写入」-> 状态文件/M3台账/风险日志首次创建时永远写不进去
#      (状态不落盘 -> 重启后重复建仓; 台账写不进 -> 当日加仓额度被重置; 告警写不进 -> 全静默)。
#      现只在「文件确实存在却读不出来」时中止写入, 文件不存在 = 首次创建, 正常落盘。
#   5) 版本收尾: 文件头版本行 + v1.2.79 变更记录块补齐(此前 v1.2.79 只有摘要、无记录块)。
#  铁律未动: 无止损/强平; 扣全费真赚才卖; 人工接管同时释放股票额度与资金额度, 原样保留。
# [v1.2.79 修改时间 2026-10-22] AUD96 全新独立审计修复(GBK 直改, 编码不变):
#   1) save_state/save_m3 读状态文件失败时中止本次写入(不再用空字典覆盖, 防清空其他股票状态导致重复建仓)
#   2) settle_pending_timeout 强制清理(_PENDING_TTL_FORCE)前先查券商活跃委托, 有活跃/未知单则保留在途台账, 防重复下单
#   3) _read_order_direction 按字段分别翻译方向(OffsetFlag 48买/49卖; Direction 0/23买 1/24卖), 统一语义 0=买/1=卖/None=未知
#   4) order_commission 异常时返回保守最低佣金而非 0, 防盈亏高估提前止盈
#   5) in_cooldown 字段类型异常时保守视为冷却中; _manual_takeover_on 配置异常时打日志
#   6) _notify_risk 风险日志读失败时中止写入, 防清空全部历史风险记录
#   7) _r1_net_profit_gate 成本完全未知时发风险告警(仍拒绝卖出, 保守)
#   8) load_state/load_m3 读失败发一次性风险告警提醒人工核对防重复建仓/超额加仓
#   9) _rebuild_pending_from_broker 断路恢复分支改 max() 合并在途台账, 防覆盖已登记在途单
#  10) query_position_safe 持仓代码匹配改大小写不敏感; init 对 ETF/转债/港股通品种打费率未分档提醒
#  11) init 异常兜底重载在途台账; 双实例锁 fail-open 时发风险告警; _sync_state_to_actual 裸 return 改 return True
#  铁律未动: 无止损/强平; 扣全费真赚才卖; 人工接管同时释放股票额度与资金额度, 原样保留。
