#      现象：15:25:22 启动日志报 trade_mode=simulation（模拟），但框架首行是 [trade]start trading mode。
#      根因：探测用固定 60 秒滑动窗口判「是否本次运行」，且首次命中即 return。用户 15:24:40
#      先在模拟模式启动过一次（框架 15:24:46 落 simulation 行），切回实盘后 15:25:22 重启，新实例
#      第一次尝试就读到 36 秒前的 simulation 行并立即返回；本轮真正的 trading 行
#      15:25:22,535 才落盘（探测已结束 0.4 秒）。
#      修复：新增 _INIT_START_TS（init 首行写入）与 _MODE_PRE_INIT_SEC=10 秒允许提前量；模式行
#      时间戳早于「init 起始 - 10 秒」一律判为上一轮残留、不采纳，改走既有的「不作
#      结论 + 首根 bar 补测」兜底（补测读到 trading，结论正确）。
#      另：模拟/回测提示补一句「若界面首行显示 [trade]start trading mode，以首行为准」。
#      影响面：_trade_mode 仅 init 内局部变量，只用于打日志与置补测标志，不参与任何交易判定，
#      本次改动零交易行为变化；铁律三条原样保留。
