#       修法：新增 _inject_dl_funcs（三路兜底：模块全局 / ContextInfo 方法 / __builtins__，
#       不依赖 xtquant），init 与每根 handlebar 幂等补注；_try_download_hist 遇空壳直接跳过。
#    ② P2【高·误报主因】门槛比实际需求多一根：调用方传 ma_long+5=65，内部无条件剔末根后
#       再要求 >=65，等价于原始必须 >=66 根——而算 MA60 只需 60 根。本地恰有 65 根即误报
#       「不足65根(实得64)」；同期个股数据门（不剔末根、只要 65 根）是通过的，于是形成
#       「明明下载了全部数据，指数却说没就绪」的观感。修法：n 语义改为「需要的已收盘根数」，
#       调用方传 ma_long(60)，请求 n+10 根、最少收 n+1 根。
#    ③ P3【高·历史 29.9077 根因】指数取数原先优先前复权(front_ratio)。指数无分红送股、
#       不存在除权，理论任何口径都等于原值；实盘却出现被缩放的两位数点位。修法：不复权
#       (none) 优先，前复权仅兜底。情绪模块成交量同步改不复权，与收盘价同源同口径。
#    ④ P4【中·指标滞后一天】指数末根原先无条件剔除。盘前或客户端未生成当日 bar 时会白剔
#       一根昨天的真数据。修法：新增 _idx_last_bar_date（按自然日缓存、每天至多查一次），
#       末根日期确认为今天才剔，未知/非当日一律保留（与个股 flag_today 同口径）。
#    ⑤ P5【中·假兜底】老接口 get_history_data 是「当前标的」取数口、不吃 code 参数，对指数
#       实际返回个股序列（实测 20 元），被护栏拦下后日志写「老接口均不可信」误导排查。
#       修法：新增 require_code，指数场景只认键名严格匹配，否则判「不适用」。
#    ⑥ P6【中低·整段作废】fill_data 补 0 会让整段序列被护栏否定。修法：只切首尾连续 0，
#       中段 0 仍交护栏判（真异常不放过）。
#    ⑦ P7【中·短序列压过长序列】_get_hist 按「口径优先于长度」择优，front 30 根会压过
