# ---- 日志/状态文件路径（可移植：不依赖本机绝对路径）----
# 优先级：GF_BASE_DIR（测试隔离/显式指定）-> __file__ 所在目录
#         -> QMT 进程当前目录(bin.x64)。
try:
    _ENV_DIR = os.environ.get("GF_BASE_DIR") or ""
except Exception:
    _ENV_DIR = ""
_BASE_DIR_SRC = "cwd"           # BASE_DIR 命中来源（env/file/cwd），init 自检输出
# PUB-1(b)(2026-10-29 修复)：发布版把 _FIXED_DIR 去掉后只剩 env/__file__/cwd 三级回退，
#   而 QMT 内置 Python 里 __file__ 通常不存在 -> 静默落到 cwd(= <QMT_ROOT>\\bin.x64)。
#   后果（报告 NI-5 实测）：原状态文件在策略目录，新路径指向 bin.x64 -> 旧状态读不到
#   -> 存量 9500 股被当成外部手工仓、且永不触发止盈。
#   现策略：① 仍优先 env(GF_BASE_DIR)；② 其次固定目录文件 gf_fixed_dir.txt（可手工指定，
#   与策略同盘的绝对路径，重启稳定）；③ 再次 __file__；④ 最后才 cwd，并【响亮告警】。
def _read_fixed_dir():
    """读取与脚本同目录的 gf_fixed_dir.txt 第一行（显式指定的绝对目录）。读不到返回 ''。"""
    try:
        _cands = []
        try:
            _cands.append(os.path.dirname(os.path.abspath(__file__)))
        except Exception:
            pass
        try:
            _cands.append(os.getcwd())
        except Exception:
            pass
        for _d in _cands:
            _f = os.path.join(_d, 'gf_fixed_dir.txt')
            if os.path.isfile(_f):
                with open(_f, 'r', encoding='utf-8', errors='ignore') as _fh:
                    _ln = (_fh.readline() or '').strip()
                if _ln:
                    return _ln
    except Exception:
        pass
    return ''

if _ENV_DIR:
    _BASE_DIR = _ENV_DIR
    _BASE_DIR_SRC = "env"
else:
    _FIXED_DIR = _read_fixed_dir()
    if _FIXED_DIR:
        _BASE_DIR = _FIXED_DIR
        _BASE_DIR_SRC = "fixed"
    else:
        try:
            _BASE_DIR = os.path.dirname(os.path.abspath(__file__))
            _BASE_DIR_SRC = "file"
        except Exception:
            _BASE_DIR = os.getcwd()
            _BASE_DIR_SRC = "cwd"
STATE_FILE = os.path.join(_BASE_DIR, "gf_native_multi_state.json")     # 多标的持仓状态(按code分桶)
M3_STATE_FILE = os.path.join(_BASE_DIR, "gf_native_multi_m3.json")       # 多标的盘中加仓状态(按code分桶)
TRADE_LOG = os.path.join(_BASE_DIR, "gf_native_trade.log")       # 交易决策日志
# P0-1 修复(2026-10-01)：在途买单台账独立持久化——内存台账 _PENDING_BUYS 进程重启即归零，
# 而状态文件在 QMT IO 沙箱下可能写入失败；在途台账丢失 + 重启 = 重复开首仓（对抗测试 C 组复现）。
PENDING_FILE = os.path.join(_BASE_DIR, "gf_native_pending.json")  # 在途买单台账持久化
# AUD59(2026-10-14)：已清仓盈亏台账持久化——sell_all 卖出成功即记账（按保守成交价×卖出股数
# 扣费后减持仓成本，得本次净到手盈亏），累计到 _PNL_HISTORY 并落盘。重启读回，盈亏历史不丢。
# 纯记账 + 每30分钟汇总日志（_pnl_display_log），零交易行为变更，铁律不受影响。
PNL_HISTORY_FILE = os.path.join(_BASE_DIR, "gf_pnl_history.json")
# P1-5 修复(2026-10-01)：数据闸门告警标志文件（外部看门狗可读；模态弹窗已移除——
# 无超时弹窗会阻塞 QMT 内置 Python 单线程，无人值守时全部策略无限期停摆）
DATA_GATE_ALERT_FILE = os.path.join(_BASE_DIR, "data_gate_alert.json")
TRADEDAY_CACHE = os.path.join(_BASE_DIR, "gf_tradeday_cache.json")  # A股交易日历缓存

# ---- AUD38(2026-10-08 功能升级)：运行文件镜像同步到某券商 QMT 用户数据目录 ----
# 用户确认方案（2026-10-08）：nbbank(_BASE_DIR) 为主目录（权威，读取优先），某券商 QMT 运行端
# userdata_mini 下 gf_qmt_mirror 为镜像副本；每次写入后自动复制；启动时主目录缺失自动从镜像
# 补回；镜像写失败仅告警（60s 去重），绝不影响主目录读写与交易。
try:
    _MIRROR_DIR = os.environ.get("GF_MIRROR_DIR") or os.path.join(_BASE_DIR, "gf_qmt_mirror")
except Exception:
    _MIRROR_DIR = os.path.join(_BASE_DIR, "gf_qmt_mirror")
_MIRROR_WARN_GAP = 60.0        # 镜像写失败告警去重间隔（秒）
_MIRROR_LAST_WARN = 0.0        # 上次镜像告警时间戳
# PUB-1(b)(2026-10-29)：BASE_DIR 落到 cwd（QMT 下多为 bin.x64）属于危险退化——
#   状态/台账会写进安装目录，重启后可能读不回旧状态（报告 NI-5：9500 股变手工仓）。
#   这里显式打一条醒目告警，便于 init 自检时一眼发现；不影响交易。
try:
    if _BASE_DIR_SRC == 'cwd':
        _bdw = ('【目录退化告警(PUB-1)】BASE_DIR 未定位到策略目录，已回退到当前工作目录 %s。'
                '状态/台账将写在该目录，重启后可能读不回旧状态。'
                '请在策略目录放 gf_fixed_dir.txt(内容为策略绝对目录) 或设置 GF_BASE_DIR。'
                % _BASE_DIR)
        try:
            log(_bdw)
        except Exception:
            print(_bdw)
except Exception:
    pass


def _mirror_copy(relname):
    """把主目录(_BASE_DIR)下某个运行文件复制到镜像目录(_MIRROR_DIR)。
    relname 为相对文件名（如 'gf_native_multi_state.json'）；目录不存在自动创建；
    AUD42(2026-10-09)：改走 _lock_and_write_impl 已验证写入通道（临时文件 + os.replace）。
    任何失败仅节流告警，绝不影响主目录读写与交易。"""
    global _MIRROR_LAST_WARN
    try:
        if not _MIRROR_DIR:
            return
        _src = os.path.join(_BASE_DIR, relname)
        if not os.path.isfile(_src):
            return
        try:
            if not os.path.isdir(_MIRROR_DIR):
                os.makedirs(_MIRROR_DIR)
        except Exception:
            pass
        _dst = os.path.join(_MIRROR_DIR, relname)
        # AUD42(2026-10-09 实盘现场排障)：QMT 沙箱按「目标是否已存在」判定——已存在文件的
        # open() 与 os.replace 一律被拒（2026-09-24 实证，见 _lock_and_write_impl 注释），
        # shutil.copy2 直接覆盖镜像旧文件必然报 Foribdden FileIO。这正是镜像同步
        # 「只有第一次成功、之后次次失败」的根因。
        # 改为复用本文件里**已在实盘长期跑通**的写入通道 _lock_and_write_impl：
        #   写全新临时文件 → os.replace 原子替换 → 删目标再替换 → 删目标后新建写出（三级兜底）；
        # 源文件读取同样走已验证的 _read_file_bytes（open → os.open → ctypes 三级链）。
        # max_bytes 传 32MB：交易日志轮转上限 10MB，留足余量避免被截断。
        _blob, _rerr = _read_file_bytes(_src, 33554432)
        if _blob is None:
            raise IOError("读取源文件失败(%s)" % _rerr)
        _lock_and_write_impl(_dst, lambda _fp: _fp.write(_blob))
    except Exception as _e:
        _tw = time.time()
        if _tw - _MIRROR_LAST_WARN >= _MIRROR_WARN_GAP:
            _MIRROR_LAST_WARN = _tw
            try:
                log("[镜像同步] 复制 %s 到某券商镜像目录失败：%s（不影响主目录读写与交易，60s 后自动重试）"
                    % (relname, _e))
            except Exception:
                pass


def _mirror_copy_trade_logs():
    """AUD38：同步交易日志本体及轮转历史（主目录存在才复制）。

    AUD53(2026-10-13)：备份份数改为随 LOG_BACKUP_COUNT 动态生成——原实现硬编码
    .1~.5，份数调大后高序号备份不会被镜像，镜像与主目录留存集不一致。
    """
    for _sfx in [""] + [".%d" % _i for _i in range(1, LOG_BACKUP_COUNT + 1)]:
        _rel = "gf_native_trade.log" + _sfx
        if os.path.isfile(os.path.join(_BASE_DIR, _rel)):
            _mirror_copy(_rel)


_MIRROR_LOG_LAST = 0.0     # AUD41：日志镜像上次同步时间戳
_MIRROR_LOG_GAP = 60.0     # AUD41：日志镜像最小同步间隔（秒）


def _mirror_trade_logs_throttled():
    """AUD41：日志镜像节流——最多每 _MIRROR_LOG_GAP 秒同步一次交易日志本体。

    原实现每写一行日志都调用 _mirror_copy_trade_logs()（复制本体 + .1~.5 共 6 个文件），
    单线程环境下 I/O 放大明显（轮转后单次可达数十 MB）。现改为：
      · 周期性同步：最多 60s 一次，仅复制日志本体（增量小）；
      · 轮转发生时（_rotate_log_if_needed）与 stop 时：各做一次完整镜像（含 .1~.5）。
    日志内容不丢，仅降低复制频率。
    """
    global _MIRROR_LOG_LAST
    _t = time.time()
    if _t - _MIRROR_LOG_LAST < _MIRROR_LOG_GAP:
        return
    _MIRROR_LOG_LAST = _t
    _mirror_copy("gf_native_trade.log")


def _mirror_remove(relname):
    """AUD38：删除主目录某个运行文件时同步删除镜像副本（如数据就绪告警标志）。"""
    try:
        if not _MIRROR_DIR:
            return
        _dst = os.path.join(_MIRROR_DIR, relname)
        if os.path.isfile(_dst):
            os.remove(_dst)
    except Exception:
        pass


def _mirror_restore(relname):
    """AUD38 启动自愈：主目录文件缺失但镜像存在时，从镜像复制回主目录（防误删丢实盘状态）。"""
    try:
        if not _MIRROR_DIR:
            return
        _src = os.path.join(_BASE_DIR, relname)
        if os.path.isfile(_src):
            return
        _dst = os.path.join(_MIRROR_DIR, relname)
        if not os.path.isfile(_dst):
            return
        import shutil
        shutil.copy2(_dst, _src)
        try:
            log("[镜像同步] 主目录缺失 %s，已从某券商镜像目录自动恢复" % relname)
        except Exception:
            pass
    except Exception:
        pass


def _mirror_restore_all():
    """AUD38：启动时对全部运行文件执行自愈恢复（主缺镜有才补回）。"""
    for _rel in ("gf_native_multi_state.json", "gf_native_pending.json",
                 "gf_native_multi_m3.json", "gf_native_trade.log",
                 "gf_risk_events.log", "gf_tradeday_cache.json",
                 "data_gate_alert.json"):
        _mirror_restore(_rel)

# ---------------------------------------------------------------------------
# 1.5 交易日判断（2026-09-25 新增，12-25 刷新逻辑升级）—— 覆盖周末 + 法定节假日 + 调休安排
# ---------------------------------------------------------------------------
# 数据源：akshare.tool_trade_date_hist_sina()  →  A股全部交易日（含调休工作日、排除节假日）
# 缓存策略：JSON 文件缓存，满足以下任一条件即重新拉取：
#   (a) 缓存覆盖的最后交易日 < 今天（明年了，需要新一年的节假日安排）
#   (b) 缓存超过 30 天（可能有新节假日安排发布）
#   (c) 每年 12 月（元旦前，交易所通常发布次年节假日安排）强制重拉
#   (d) 每年 1 月（元旦后，节假日安排应已发布）强制重拉
# 降级链：akshare在线 → 本地JSON缓存 → 内置节假日表 → 仅周末判断 → 拦截（见 1.5A）
_TRADEDAY_SET = None          # 内存缓存：set of 'YYYY-MM-DD'
_TRADEDAY_LAST_DATE = ""      # 缓存覆盖的最后交易日 'YYYY-MM-DD'。
                              # AUD83-P7：本变量全文无任何读取点，仅作排障留痕；
                              # 交易日判定实际以 _TRADEDAY_SET 集合为准，本字段不参与任何判定。
_TRADEDAY_FETCHED_AT = ""     # 缓存拉取时间 'YYYY-MM-DD HH:MM:SS'
_TRADEDAY_LAST_CHECK = ""     # 上次「完整尝试」的日期；成功失败都记，用于当天只试一次


_TRADEDAY_REFRESH_INTERVAL = 30   # 缓存超过多少天强制刷新


def _fetch_trade_dates_from_akshare():
    """拉取 A 股全部交易日列表，返回 (set, max_date_str) 或 (None, '')（失败）。"""
    try:
        import akshare as _ak
        _df = _ak.tool_trade_date_hist_sina()
        if _df is None or len(_df) == 0:
            return None, ""
        _col = _df.columns[0]
        _out = set()
        _max = ""
        for _v in _df[_col].values:
            try:
                if hasattr(_v, "strftime"):
                    _s = _v.strftime("%Y-%m-%d")
                else:
                    _s = str(_v)[:10]
                _out.add(_s)
                if _s > _max:
                    _max = _s
            except Exception:
                pass
        return (_out, _max) if _out else (None, "")
    except Exception:
        return None, ""


def _load_trade_dates_from_cache():
    """从本地 JSON 缓存加载交易日集合，返回 (set, last_date, fetched_at) 或 (None, '', '')。"""
    try:
        _blob, _err = _read_file_bytes(TRADEDAY_CACHE)
        if _blob is None:
            return None, "", ""
        _data = json.loads(_blob.decode("utf-8"))
        if isinstance(_data, dict) and "trade_dates" in _data:
            return (set(_data["trade_dates"]),
                    _data.get("last_date", ""),
                    _data.get("fetched_at", _data.get("refresh_date", "")))
    except Exception:
        pass
    return None, "", ""


def _save_trade_dates_cache(date_set, last_date):
    """把交易日集合写入 JSON 缓存文件。"""
    try:
        _payload = {
            "fetched_at": datetime.now().strftime("%Y-%m-%d %H:%M:%S"),
            "last_date": last_date,
            "trade_dates": sorted(date_set),
        }
        def _w(fp):
            fp.write(json.dumps(_payload, ensure_ascii=False).encode("utf-8"))
        _lock_and_write(TRADEDAY_CACHE, _w)
        _mirror_copy("gf_tradeday_cache.json")   # AUD38：镜像同步到某券商 QMT 目录
    except Exception:
        pass


def _should_refresh_cache(today_date, cache_last_date, cache_fetched_at):
    """判断缓存是否需要刷新。

    返回 (need_refresh: bool, reason: str)
    """
    # (a) 缓存覆盖的最后交易日 < 今天 → 明年了，必须重拉
    if cache_last_date:
        try:
            _cache_last = datetime.strptime(cache_last_date[:10], "%Y-%m-%d").date()
            if _cache_last < today_date:
                return True, f"缓存覆盖到{cache_last_date}，已过期"
        except Exception:
            pass

    # (b) 缓存超过 N 天 → 可能有新节假日安排
    if cache_fetched_at:
        try:
            _fetched = datetime.strptime(cache_fetched_at[:10], "%Y-%m-%d").date()
            _delta = (today_date - _fetched).days
            if _delta >= _TRADEDAY_REFRESH_INTERVAL:
                return True, f"缓存已{_delta}天未刷新"
        except Exception:
            pass

    # (c) 每年 12 月（元旦前）→ 交易所通常发布次年节假日安排
    if today_date.month == 12:
        if cache_fetched_at:
            try:
                _fetched = datetime.strptime(cache_fetched_at[:10], "%Y-%m-%d").date()
                if _fetched.year < today_date.year or _fetched.month < 12:
                    return True, "12月元旦前强制刷新（等待次年节假日安排）"
            except Exception:
                pass
        else:
            return True, "12月元旦前强制刷新（无缓存）"

    # (d) 每年 1 月（元旦后）→ 节假日安排应已发布
    if today_date.month == 1:
        if cache_fetched_at:
            try:
                _fetched = datetime.strptime(cache_fetched_at[:10], "%Y-%m-%d").date()
                if _fetched.year < today_date.year:
                    return True, "1月元旦后强制刷新（新一年节假日安排应已发布）"
            except Exception:
                pass
        else:
            return True, "1月元旦后强制刷新（无缓存）"

    return False, ""


# ---------------------------------------------------------------------------
# 1.5A 内置法定节假日表（2026-10-19 第十五轮补充，零依赖兜底）—— 专为 QMT 内置 python 而设
# ---------------------------------------------------------------------------
# 【为什么要加这一段】
#   交易日判断原有降级链是：akshare 在线拉取 → 本地 JSON 缓存 → 只看周末 → 无法判断。
#   某券商 QMT 内置 python 里没有装 akshare，本地缓存 gf_tradeday_cache.json 又已被清理，
#   于是降级链一路掉到最后一环。第十四轮 R-3 再把最后一环由「放行」改成「拦截」，
#   结果就是每个交易日都被判成「无法确认」→ 全天静默不交易，策略等于停摆。
#   本表把 2026 年沪深北交易所公布的休市安排直接写死在代码里——不联网、不读缓存、
#   不依赖任何第三方库，在 QMT 内置 python 里天生可用。
#
# 【关键坑：周末不能一律当休市】
#   2026 年有 5 天是「周末补班、但交易所照常开市」：2/14(六)、2/28(六) 春节调休，
#   5/9(六) 劳动节调休，9/20(日)、10/10(六) 国庆调休。若简单地「周六周日一律不开市」，
#   这 5 个真交易日会被误判成休市，策略白白停 5 天。故单独列出，优先级高于「周末=休市」。
#
# 【超出年份怎么办】
#   本表只覆盖 2026 年。跨到 2027 年后 _builtin_trade_day_check 返回「不覆盖」，
#   由 is_trade_day 继续往下走「仅周末 + 拦截」的保守兜底，绝不拿旧表硬套新年份，
#   并在 init 打「节假日表过期告警」提示补表。
#
# 官方依据：证监办发〔2025〕130 号；上证公告〔2025〕45 号 / 深证会〔2025〕481 号 /
#           北证公告〔2025〕58 号（均 2025-12-22 发布）
_BUILTIN_CLOSED_WORKDAYS = {2026: frozenset((
    "2026-01-01", "2026-01-02",                              # 元旦 1/1(四)~1/3(六) 休市，1/4(日)为周末
    "2026-02-16", "2026-02-17", "2026-02-18",                # 春节 2/15(日)~2/23(一) 休市
    "2026-02-19", "2026-02-20", "2026-02-23",                #   其中 2/21、2/22 为周末
    "2026-04-06",                                            # 清明 4/4(六)~4/6(一) 休市
    "2026-05-01", "2026-05-04", "2026-05-05",                # 劳动节 5/1(五)~5/5(二) 休市
    "2026-06-19",                                            # 端午 6/19(五)~6/21(日) 休市
    "2026-09-25",                                            # 中秋 9/25(五)~9/27(日) 休市；9/28(一) 照常开市
    "2026-10-01", "2026-10-02", "2026-10-05",                 # 国庆 10/1(四)~10/7(三) 休市
    "2026-10-06", "2026-10-07",                              #   其中 10/3、10/4 为周末
))}

_BUILTIN_OPEN_WEEKENDS = {}  # N14：A股交易所周末一律休市，不采用调休补班日



def _builtin_trade_day_check(d):
    """内置节假日表判定某一天是不是 A 股交易日。

    参数 d：datetime.date（只用到年月日）
    返回 (is_trade, source)：
      (True / False, "builtin") —— 本表覆盖该年份，已给出确定答案；
      (None, "")                 —— 本表不覆盖该年份（由调用方自行决定兜底口径）。
    """
    _yr = getattr(d, "year", None)
    if _yr not in _BUILTIN_CLOSED_WORKDAYS:
        return None, ""                       # 年份不在表内 → 不给答案，绝不拿旧表硬套新年份
    _key = "%04d-%02d-%02d" % (_yr, d.month, d.day)
    if _key in _BUILTIN_CLOSED_WORKDAYS.get(_yr, ()):
        return False, "builtin"               # 法定节假日：周一至周五，但休市
    if d.weekday() >= 5:
        return False, "builtin"               # 普通周末
    return True, "builtin"                    # 普通工作日


def _init_trade_day_set():
    """初始化交易日集合：优先 akshare 在线拉取，失败则读缓存，再失败则置空交由内置节假日表。

    同一自然日内只做一次完整尝试（成功或失败都算），由 _TRADEDAY_LAST_CHECK 记录，
    避免 handlebar 每几秒就重跑一次注定失败的 akshare 导入与缓存读取。
    """
    global _TRADEDAY_SET, _TRADEDAY_LAST_DATE, _TRADEDAY_FETCHED_AT, _TRADEDAY_LAST_CHECK
    _today_date = datetime.now().date()
    _today_str = _today_date.strftime("%Y-%m-%d")

    # 同一自然日内已完整尝试过（无论成功还是失败）→ 直接返回，不再重试
    # T-4(2026-10-19 第十六轮补充·用户拍板「改」)：原判断写成
    #   `if _TRADEDAY_SET is not None and _TRADEDAY_LAST_CHECK == _today_str`，
    #   额外要求「已经取到交易日集合」。而「akshare 没装 + 缓存文件缺失」这种全失败场景下
    #   _TRADEDAY_SET 恒为 None，这道保险丝永远不触发——于是 handlebar 每几秒调一次
    #   is_trade_day、每次都重新 import 一个并不存在的 akshare、重新读一次并不存在的缓存。
    #   _TRADEDAY_LAST_CHECK 只在一次完整尝试走完时才写（成功失败都写），直接拿它当
    #   「今天已经试过了」的标记即可：失败路径每天只白费一次力气，结果照旧交给内置节假日表。
    #   注意：两个调用点（is_trade_day / previous_trading_day）都只调用、不取返回值，
    #   故此行改为返回 _TRADEDAY_SET is not None 对外行为无影响。
    if _TRADEDAY_LAST_CHECK == _today_str:
        return _TRADEDAY_SET is not None

    # 先尝试从缓存加载，再决定是否需要在线刷新
    _cached_set, _cached_last, _cached_fetched = _load_trade_dates_from_cache()

    _need_refresh = True   # 默认尝试在线拉取
    if _cached_set is not None:
        _need_refresh, _reason = _should_refresh_cache(
            _today_date, _cached_last, _cached_fetched)
        if not _need_refresh:
            # 缓存仍然有效 → 直接用
            _TRADEDAY_SET = _cached_set
            _TRADEDAY_LAST_DATE = _cached_last
            _TRADEDAY_FETCHED_AT = _cached_fetched
            _TRADEDAY_LAST_CHECK = _today_str
            return True

    # 在线拉取
    _online_set, _online_last = _fetch_trade_dates_from_akshare()
    if _online_set is not None:
        _TRADEDAY_SET = _online_set
        _TRADEDAY_LAST_DATE = _online_last
        _TRADEDAY_FETCHED_AT = _today_str
        _TRADEDAY_LAST_CHECK = _today_str
        _save_trade_dates_cache(_online_set, _online_last)
        return True

    # 在线失败 → 退回到缓存
    if _cached_set is not None:
        _TRADEDAY_SET = _cached_set
        _TRADEDAY_LAST_DATE = _cached_last
        _TRADEDAY_FETCHED_AT = _cached_fetched
        _TRADEDAY_LAST_CHECK = _today_str
        return True

    # 全部失败 → 置空，交由 is_trade_day 按「内置节假日表 → 仅周末 → 拦截」逐级兜底
    _TRADEDAY_SET = None
    _TRADEDAY_LAST_DATE = ""
    _TRADEDAY_FETCHED_AT = ""
    _TRADEDAY_LAST_CHECK = _today_str
    return False


def is_trade_day(today=None):
    """判断给定日期是否为 A 股交易日（覆盖周末 + 法定节假日 + 调休）。

    参数 today: datetime.date / datetime / 'YYYY-MM-DD' / None(=今天)
    返回 (is_trade: bool, source: str):
      source ∈ {'akshare'(在线拉取), 'cache'(本地缓存), 'weekend_fallback'(仅周末), 'unknown'(无法判断)}
    """
    if today is None:
        _d = datetime.now().date()
    elif isinstance(today, str):
        _d = datetime.strptime(today[:10], "%Y-%m-%d").date()
    elif hasattr(today, "date"):
        _d = today.date()
    else:
        _d = today
    _key = _d.strftime("%Y-%m-%d")

    _init_trade_day_set()

    if _TRADEDAY_SET is not None:
        # N6(2026-10-29 修复)：只在【缓存确实覆盖该日期】时才用集合作答。
        #   原实现只要 _TRADEDAY_SET 非空就直接 return (_key in 集合)，而缓存往往只到某个
        #   日期为止（如只到 2026-12-31）；跨年后查询 2027-01-04 落在集合外 -> 直接判
        #   「不是交易日」-> 整日停摆，连止盈都被挡下（报告 N6/NB-1）。
        #   现改为：日期超出缓存覆盖范围时不下结论，继续往下走内置节假日表/工作日兜底。
        _cov_ok = True
        if _TRADEDAY_LAST_DATE:
            try:
                _cov_ok = (_key <= str(_TRADEDAY_LAST_DATE)[:10])
            except Exception:
                _cov_ok = True
        if _cov_ok:
            _src = "akshare" if (_TRADEDAY_FETCHED_AT and _TRADEDAY_FETCHED_AT[:10] == _key) else "cache"
            return (_key in _TRADEDAY_SET, _src)
        # 超出覆盖范围：落到下方 builtin / 工作日兜底

    # T-1(2026-10-19 第十五轮补充)：内置 2026 节假日表兜底（零依赖，不联网、不读缓存、不装任何库）。
    #   取值优先级：akshare在线 > 本地缓存 > 内置节假日表 > 仅看周末 > 拦截。
    #   加这一层是为了让「QMT 内置 python 没有 akshare + 本地缓存已被清理」的环境下，交易日
    #   仍然照常能跑策略，同时不破坏 R-3 的 fail-closed 口径（真正拿不准时仍然全天拦截）。
    _bi_is_trade, _bi_src = _builtin_trade_day_check(_d)
    if _bi_is_trade is not None:
        return (bool(_bi_is_trade), _bi_src)

    # 降级：仅判断周末
    _wd = _d.weekday()   # 0=Monday, 6=Sunday
    if _wd >= 5:
        return (False, "weekend_fallback")
    # R-3(2026-10-19 第十四轮独立审计·用户拍板方案A)：工作日兜底由「放行」改为「拦截」。
    #   原注释写「防御拦截，宁可错过不可错买」但代码是 return (True, "unknown")（True=是交易日=放行），
    #   注释与实现完全相反。逢法定节假日且 akshare 拉取失败 + 本地缓存缺失时，策略会误判
    #   「今天是交易日」继续跑交易逻辑，理论上可在假日提交委托（券商侧会拒单）。
    #   现按注释的原本意图改为 return (False, "unknown")：拿不准时全天不交易。
    #   说明：T-1 内置节假日表已把 2026 年绝大多数情况挡在前面；能走到这里只剩「年份超出表内范围」
    #   （如 2027 年及以后）且缓存也读不到这一种情况。属「宁可错过不可错买」的保守取舍，与数据门 fail-closed 口径一致。
    #   init 会打印「数据源=无法确认」并说明当日交易判定为保守放行。
    #
    # N6(2026-10-29 修复)：由「全天拦截」改为「工作日放行 + 醒目告警」。
    #   原因：原策略在「缓存覆盖不到 + 内置表无该年份」时直接判定非交易日，会把当天
    #   所有动作全部停掉，连止盈都跑不了（漏卖比误买风险更大，且次日不会自动补）。
    #   现在的工作日兜底口径：
    #     · 周六/周日 -> 休市（已在上面 return）
    #     · 周一至周五 -> 视为交易日放行，safe：passorder 若逢真假日会被券商拒单，
    #       策略侧有拒单退避与冷却，不会造成实际损失；而漏掉止盈的代价更高。
    #   init 阶段仍会通过 source='weekday_fallback' 打出「节假日表缺失请补表」告警。
    # P2-5(2026-10-30 评审修复)：改回 (False, "unknown")。
    #   N6 曾改成 (True,"weekday_fallback") 想"工作日放行"，但 _determine_trade_mode
    #   只有在 ok is False and src == "unknown" 时才进 "sell_only" 只卖不买模式 ——
    #   返回 True 后 L2578 直接走 "normal"，整个 sell_only 降级与 _mode_pending_recheck
    #   都变成死代码；在未缓存的工作日法定假日（如日历只到 2026-12-31 时的 2027-01-01）
    #   策略会照常发实盘买单。宁可错过不可错买，恢复保守语义。
    return (False, "unknown")


def previous_trading_day(day_str, max_back=15):
    """上一交易日（YYYY-MM-DD）——AUD68(2026-10-16) 补齐缺失函数。
    此前 _hdiag_log 调用本函数但全文未定义，NameError 被 try/except 吞掉，半时诊断的
    「指标末根日期」退化为占位文字。优先用交易日集合（覆盖节假日/调休），集合不可用时
    按自然日跳过周末回退；任何异常返回空串（调用方已有兜底）。"""
    try:
        from datetime import timedelta as _td68
        _d = datetime.strptime(str(day_str)[:10], "%Y-%m-%d").date()
        _init_trade_day_set()
        for _i in range(1, max_back + 1):
            _p = _d - _td68(days=_i)
            _ps = _p.strftime("%Y-%m-%d")
            if _TRADEDAY_SET is not None:
                if _ps in _TRADEDAY_SET:
                    return _ps
            else:
                # T-1(2026-10-19 第十五轮补充)：无交易日集合时改用内置节假日表回溯，比原
                #   「只看周一~周五」准确——既会跳过法定节假日，也能正确认到周末补班日。
                _bi_ok, _ = _builtin_trade_day_check(_p)
                if _bi_ok is True:
                    return _ps
                if _bi_ok is None and _p.weekday() < 5:
                    return _ps          # 内置表不覆盖该年份 → 退回原来的「只看周一~周五」
        return (_d - _td68(days=1)).strftime("%Y-%m-%d")
    except Exception:
        return ""


